seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">")).upper()
L=len(seq)
compl = str.maketrans("ACGT","TGCA")
def rc(s): return s.translate(compl)[::-1]

CODE = {
'TTT':'F','TTC':'F','TTA':'L','TTG':'L','TCT':'S','TCC':'S','TCA':'S','TCG':'S',
'TAT':'Y','TAC':'Y','TAA':'*','TAG':'*','TGT':'C','TGC':'C','TGA':'*','TGG':'W',
'CTT':'L','CTC':'L','CTA':'L','CTG':'L','CCT':'P','CCC':'P','CCA':'P','CCG':'P',
'CAT':'H','CAC':'H','CAA':'Q','CAG':'Q','CGT':'R','CGC':'R','CGA':'R','CGG':'R',
'ATT':'I','ATC':'I','ATA':'I','ATG':'M','ACT':'T','ACC':'T','ACA':'T','ACG':'T',
'AAT':'N','AAC':'N','AAA':'K','AAG':'K','AGT':'S','AGC':'S','AGA':'R','AGG':'R',
'GTT':'V','GTC':'V','GTA':'V','GTG':'V','GCT':'A','GCC':'A','GCA':'A','GCG':'A',
'GAT':'D','GAC':'D','GAA':'E','GAG':'E','GGT':'G','GGC':'G','GGA':'G','GGG':'G'}
def tr(s): return "".join(CODE[s[i:i+3]] for i in range(0,len(s),3) if len(s[i:i+3])==3)

STOPS=frozenset("TAA TAG TGA".split()); STARTS=frozenset("ATG".split())

def orf_scan(ss, min_aa=50):
    res=[]
    for start in STARTS:
        for i in range(0,len(ss)-2):
            if ss[i:i+3]==start:
                j=i
                while j+3<=len(ss) and ss[j:j+3] not in STOPS:
                    j+=3
                aa=(j-i)//3
                if aa>=min_aa:
                    res.append((i, j+3, aa, ss[i:j+3]))
    return res

def genomic_from_plus(i,j,aa,p):
    return ("+", i+1, j, aa, tr(p))

def genomic_from_minus(i,j,aa,p):
    # rs index k -> genomic L - k (1-based). ORF covers rs i..j-1 -> genomic (L-j+1)..(L-i)
    return ("-", L-j+1, L-i, aa, tr(p))

plus = [genomic_from_plus(*o) for o in orf_scan(seq)]
minus = [genomic_from_minus(*o) for o in orf_scan(rc(seq))]
allorfs = sorted(plus+minus, key=lambda x:-x[2])
for o in allorfs[:20]:
    print("strand %s  genomic %d-%d  %d aa" % (o[0], o[1], o[2], o[3]))
    print("   protein:", o[4])
    print()
